using System.Text.Json.Serialization;
using System.Text;
using System.Net.Http.Json;
using System.Security.Claims;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Pathway.Api;

var builder = WebApplication.CreateBuilder(args);
builder.WebHost.ConfigureKestrel(options => options.Limits.MaxRequestBodySize = 512 * 1024);
builder.Services.ConfigureHttpJsonOptions(options => options.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));
builder.Services.AddHttpClient("evaluator", client => client.Timeout = TimeSpan.FromSeconds(15));
builder.Services.AddHttpClient("coach", client => client.Timeout = TimeSpan.FromSeconds(12));
builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.OnRejected = (context, _) =>
    {
        context.HttpContext.Response.Headers.RetryAfter = "60";
        return ValueTask.CompletedTask;
    };
    options.AddPolicy("public-read", context => FixedWindow(context, permitLimit: 180));
    options.AddPolicy("learner", context => LearnerWindow(context, permitLimit: 90));
    options.AddPolicy("submission", context => LearnerWindow(context, permitLimit: 10));
    options.AddPolicy("coach", context => FixedWindow(context, permitLimit: 20));
    options.AddPolicy("community-write", context => FixedWindow(context, permitLimit: 15));
});
var databaseUrl = builder.Configuration["DATABASE_URL"] ?? builder.Configuration.GetConnectionString("Pathway");
if (!string.IsNullOrWhiteSpace(databaseUrl))
    builder.Services.AddDbContextFactory<ProgressDbContext>(options => options.UseNpgsql(ToNpgsqlConnectionString(databaseUrl)));
var allowedOrigins = (builder.Configuration["CORS_ORIGINS"] ?? "http://localhost:5173,http://127.0.0.1:5173")
    .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
builder.Services.AddCors(options => options.AddDefaultPolicy(policy => policy.WithOrigins(allowedOrigins).AllowAnyHeader().AllowAnyMethod()));
builder.Services.AddAuthorization();
var keycloakAuthority = builder.Configuration["KEYCLOAK_AUTHORITY"]?.TrimEnd('/');
var keycloakAudience = builder.Configuration["KEYCLOAK_AUDIENCE"];
if (builder.Environment.IsProduction() && (string.IsNullOrWhiteSpace(keycloakAuthority) || string.IsNullOrWhiteSpace(keycloakAudience)))
    throw new InvalidOperationException("KEYCLOAK_AUTHORITY and KEYCLOAK_AUDIENCE are required in production.");
if (!string.IsNullOrWhiteSpace(keycloakAuthority) && !string.IsNullOrWhiteSpace(keycloakAudience))
{
    builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(options =>
    {
        options.Authority = keycloakAuthority;
        options.Audience = keycloakAudience;
        options.MapInboundClaims = false;
        options.RequireHttpsMetadata = !builder.Environment.IsDevelopment();
    });
}

var app = builder.Build();
app.UseExceptionHandler(exceptionApp => exceptionApp.Run(async context =>
{
    context.Response.StatusCode = StatusCodes.Status500InternalServerError;
    await context.Response.WriteAsJsonAsync(new { message = "An unexpected server error occurred." });
}));
app.Use(async (context, next) =>
{
    context.Response.Headers["X-Content-Type-Options"] = "nosniff";
    context.Response.Headers["X-Frame-Options"] = "DENY";
    context.Response.Headers["Referrer-Policy"] = "no-referrer";
    context.Response.Headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()";
    context.Response.Headers["Content-Security-Policy"] = "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'";
    if (app.Environment.IsProduction()) context.Response.Headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains";
    await next(context);
});
app.UseCors();
app.UseRateLimiter();
if (!string.IsNullOrWhiteSpace(keycloakAuthority) && !string.IsNullOrWhiteSpace(keycloakAudience))
{
    app.UseAuthentication();
    app.UseAuthorization();
}
if (!string.IsNullOrWhiteSpace(databaseUrl))
{
    await using var scope = app.Services.CreateAsyncScope();
    var database = scope.ServiceProvider.GetRequiredService<IDbContextFactory<ProgressDbContext>>();
    await using var context = await database.CreateDbContextAsync();
    await context.Database.EnsureCreatedAsync();
    await EnsureLearningExperienceSchema(context);
}
app.MapGet("/health", () => Results.Ok(new { status = "ok", courseVersion = Curriculum.Version })).RequireRateLimiting("public-read");
app.MapGet("/ready", async (IServiceProvider services, CancellationToken cancellationToken) =>
{
    var factory = services.GetService<IDbContextFactory<ProgressDbContext>>();
    if (factory is null) return Results.Problem("The progress database is not configured.", statusCode: StatusCodes.Status503ServiceUnavailable);
    await using var database = await factory.CreateDbContextAsync(cancellationToken);
    return await database.Database.CanConnectAsync(cancellationToken)
        ? Results.Ok(new { status = "ready" })
        : Results.Problem("The progress database is unavailable.", statusCode: StatusCodes.Status503ServiceUnavailable);
}).RequireRateLimiting("public-read");
app.MapGet("/openapi/v1.json", () => Results.Ok(new { openapi = "3.0.3", info = new { title = "Pathway API", version = "v1" } })).RequireRateLimiting("public-read");
app.MapGet("/api/courses", () => Results.Ok(Curriculum.Catalog)).RequireRateLimiting("public-read");
app.MapGet("/api/courses/{courseId}", (string courseId) => Curriculum.Courses.TryGetValue(courseId, out var course) ? Results.Ok(course) : Results.NotFound()).RequireRateLimiting("public-read");
app.MapGet("/api/lessons/{slug}", (string slug) => Curriculum.BySlug.TryGetValue(slug, out var lesson) ? Results.Ok(lesson) : Results.NotFound()).RequireRateLimiting("public-read");
var progressEndpoint = app.MapGet("/api/progress", async (HttpContext httpContext, IServiceProvider services, CancellationToken cancellationToken) =>
{
    var learnerId = await ResolveLearnerId(httpContext, services, cancellationToken);
    var factory = services.GetService<IDbContextFactory<ProgressDbContext>>();
    if (factory is null) return Results.Ok(new LearnerProgressResponse(learnerId, []));
    await using var database = await factory.CreateDbContextAsync(cancellationToken);
    var completed = await database.Progress.Where(item => item.LearnerId == learnerId).OrderBy(item => item.CompletedAt).Select(item => item.LessonSlug).ToArrayAsync(cancellationToken);
    return Results.Ok(new LearnerProgressResponse(learnerId, completed));
});
progressEndpoint.RequireRateLimiting("learner");
var submissionEndpoint = app.MapPost("/api/submissions/validate", async (Submission submission, HttpContext httpContext, IServiceProvider services, IHttpClientFactory httpClientFactory, IConfiguration configuration, IHostEnvironment environment, CancellationToken cancellationToken) =>
{
    if (!Curriculum.BySlug.TryGetValue(submission.LessonSlug, out var lesson)) return Results.NotFound();
    if ((submission.Answer?.Length ?? 0) > 200 || Encoding.UTF8.GetByteCount(submission.Code ?? string.Empty) > 50_000)
        return Results.BadRequest(new { message = "Answers must be under 200 characters and code must be at most 50 KB." });
    if (lesson.Exercise.Kind == ExerciseKind.Code && !string.IsNullOrWhiteSpace(configuration["EVALUATOR_URL"]))
    {
        var evaluatorSharedSecret = configuration["EVALUATOR_SHARED_SECRET"];
        if (environment.IsProduction() && string.IsNullOrWhiteSpace(evaluatorSharedSecret))
            return Results.Problem("The code evaluator is not securely configured.", statusCode: StatusCodes.Status503ServiceUnavailable);
        var client = httpClientFactory.CreateClient("evaluator");
        try
        {
            using var runnerRequest = new HttpRequestMessage(HttpMethod.Post, $"{configuration["EVALUATOR_URL"]!.TrimEnd('/')}/evaluate")
            {
                Content = JsonContent.Create(new EvaluatorRequest(submission.LessonSlug, submission.Code ?? string.Empty))
            };
            if (!string.IsNullOrWhiteSpace(evaluatorSharedSecret))
                runnerRequest.Headers.TryAddWithoutValidation("X-Pathway-Runner-Key", evaluatorSharedSecret);
            var runnerResponse = await client.SendAsync(runnerRequest, cancellationToken);
            if (runnerResponse.IsSuccessStatusCode)
            {
                var evaluated = await runnerResponse.Content.ReadFromJsonAsync<ValidationResult>(cancellationToken: cancellationToken);
                if (evaluated is not null)
                {
                    var reviewed = evaluated with { CodeReview = evaluated.CodeReview ?? BuildCodeReview(lesson, submission.Code ?? string.Empty) };
                    await PersistSubmission(services, await ResolveLearnerId(httpContext, services, cancellationToken), submission, reviewed.Passed, cancellationToken);
                    return Results.Ok(reviewed);
                }
            }
            return Results.Problem("The code evaluator did not return a usable result.", statusCode: StatusCodes.Status503ServiceUnavailable);
        }
        catch (HttpRequestException)
        {
            return Results.Problem("The code evaluator is temporarily unavailable.", statusCode: StatusCodes.Status503ServiceUnavailable);
        }
    }
    // Development-only deterministic checks make local lesson authoring fast. In production,
    // set EVALUATOR_URL to a private sandbox worker; never execute learner code in this API.
    if (lesson.Exercise.Kind == ExerciseKind.Code && environment.IsProduction())
        return Results.Ok(new ValidationResult(false, 0, 0, "Automated execution is not configured yet. Your static code review is ready below; a sandbox evaluator is required before code can be marked complete.", null, BuildCodeReview(lesson, submission.Code ?? string.Empty)));
    var validation = lesson.Exercise.Kind switch
    {
        ExerciseKind.MultipleChoice => ValidateChoice(lesson, submission.Answer),
        ExerciseKind.Code => ValidateCode(lesson, submission.Code ?? string.Empty),
        _ => new ValidationResult(false, 0, 1, "This exercise type is not supported yet.", null)
    };
    await PersistSubmission(services, await ResolveLearnerId(httpContext, services, cancellationToken), submission, validation.Passed, cancellationToken);
    return Results.Ok(validation);
});
submissionEndpoint.RequireRateLimiting("submission");
var experienceEndpoints = app.MapLearningExperienceEndpoints();
if (!string.IsNullOrWhiteSpace(keycloakAuthority) && !string.IsNullOrWhiteSpace(keycloakAudience)) { progressEndpoint.RequireAuthorization(); submissionEndpoint.RequireAuthorization(); experienceEndpoints.RequireAuthorization(); }
app.Run();

static Task<string> ResolveLearnerId(HttpContext context, IServiceProvider services, CancellationToken cancellationToken)
{
    var subject = context.User.FindFirstValue("sub");
    return Task.FromResult(!string.IsNullOrWhiteSpace(subject) ? $"keycloak:{subject}" : context.Request.Headers["X-Learner-Id"].FirstOrDefault() is { Length: > 0 and <= 100 } learnerId ? learnerId : "anonymous");
}

static async Task PersistSubmission(IServiceProvider services, string learnerId, Submission submission, bool passed, CancellationToken cancellationToken)
{
    var factory = services.GetService<IDbContextFactory<ProgressDbContext>>();
    if (factory is null) return;
    await using var database = await factory.CreateDbContextAsync(cancellationToken);
    database.Submissions.Add(new LearnerSubmission { LearnerId = learnerId, LessonSlug = submission.LessonSlug, Answer = submission.Answer, Code = submission.Code, Passed = passed });
    if (passed && !await database.Progress.AnyAsync(item => item.LearnerId == learnerId && item.LessonSlug == submission.LessonSlug, cancellationToken))
        database.Progress.Add(new LearnerProgress { LearnerId = learnerId, LessonSlug = submission.LessonSlug, CompletedAt = DateTimeOffset.UtcNow });
    if (passed)
    {
        var existingReview = await database.ReviewSchedules.SingleOrDefaultAsync(item => item.LearnerId == learnerId && item.LessonSlug == submission.LessonSlug, cancellationToken);
        if (existingReview is null)
            database.ReviewSchedules.Add(new ReviewSchedule { LearnerId = learnerId, LessonSlug = submission.LessonSlug, IntervalDays = 1, LastReviewedAt = DateTimeOffset.UtcNow, DueAt = DateTimeOffset.UtcNow.AddDays(1) });
        else
        {
            existingReview.IntervalDays = Math.Min(existingReview.IntervalDays * 2, 30);
            existingReview.LastReviewedAt = DateTimeOffset.UtcNow;
            existingReview.DueAt = DateTimeOffset.UtcNow.AddDays(existingReview.IntervalDays);
        }
    }
    await database.SaveChangesAsync(cancellationToken);
}

static RateLimitPartition<string> FixedWindow(HttpContext context, int permitLimit)
{
    var subject = context.User.FindFirstValue("sub");
    var key = !string.IsNullOrWhiteSpace(subject) ? $"user:{subject}" : $"ip:{context.Connection.RemoteIpAddress?.ToString() ?? "unknown"}";
    return RateLimitPartition.GetFixedWindowLimiter(key, _ => new FixedWindowRateLimiterOptions
    {
        PermitLimit = permitLimit,
        Window = TimeSpan.FromMinutes(1),
        QueueLimit = 0,
        AutoReplenishment = true
    });
}

static RateLimitPartition<string> LearnerWindow(HttpContext context, int permitLimit)
{
    var subject = context.User.FindFirstValue("sub");
    var guest = context.Request.Headers["X-Learner-Id"].FirstOrDefault();
    var key = !string.IsNullOrWhiteSpace(subject) ? $"user:{subject}" : !string.IsNullOrWhiteSpace(guest) && guest.Length <= 100 ? $"guest:{guest}" : $"ip:{context.Connection.RemoteIpAddress?.ToString() ?? "unknown"}";
    return RateLimitPartition.GetFixedWindowLimiter(key, _ => new FixedWindowRateLimiterOptions
    {
        PermitLimit = permitLimit,
        Window = TimeSpan.FromMinutes(1),
        QueueLimit = 0,
        AutoReplenishment = true
    });
}

static string ToNpgsqlConnectionString(string value)
{
    if (!Uri.TryCreate(value, UriKind.Absolute, out var uri) || (uri.Scheme != "postgres" && uri.Scheme != "postgresql")) return value;
    var userInfo = uri.UserInfo.Split(':', 2);
    var builder = new Npgsql.NpgsqlConnectionStringBuilder { Host = uri.Host, Port = uri.Port, Database = uri.AbsolutePath.Trim('/'), Username = Uri.UnescapeDataString(userInfo[0]), Password = userInfo.Length > 1 ? Uri.UnescapeDataString(userInfo[1]) : string.Empty, SslMode = Npgsql.SslMode.Require };
    return builder.ConnectionString;
}

