        new("internet-devices", "Computing & internet foundations", 1, "What a computer actually does", "Understand the machine before asking it to run code.", "A computer accepts input, processes instructions, stores state, and produces output.", "Programs are instructions represented as data. The CPU executes instructions, memory holds active data, and storage preserves data after power is off. An operating system coordinates hardware and lets many programs share it safely.", "input → program instructions → CPU and memory → output", new(ExerciseKind.MultipleChoice, "Name the role", "Which component holds a program's active working data?", ["Choose one answer"], null, "memory", [new("memory", "Memory (RAM)"), new("storage", "Long-term storage only"), new("screen", "The display")], "Running programs need fast temporary working space.", ["Explains computer roles"]), "internet-bits-bytes", WebFoundations),
        new("internet-bits-bytes", "Computing & internet foundations", 2, "Bits, bytes, and text", "All digital information is encoded as numbers.", "A bit has two states; a byte is eight bits; encodings map numbers to characters.", "Images, audio, source code, and network messages are all bytes. UTF-8 is a common text encoding. A type tells the program how to interpret bytes and what operations are valid.", "A = 65 in ASCII and UTF-8\nbyte = 8 bits", new(ExerciseKind.MultipleChoice, "Read the unit", "How many bits are in one byte?", ["Choose one answer"], null, "eight", [new("four", "4"), new("eight", "8"), new("sixteen", "16")], "A byte is the common unit used to measure digital data.", ["Connects bytes and data"]), "internet-processes", WebFoundations),
        new("internet-processes", "Computing & internet foundations", 3, "Programs, processes, and files", "A program on disk becomes a process when it runs.", "A process has its own executing instructions and memory; files provide durable bytes.", "Your editor, browser, and .NET app are separate processes. A crash normally ends one process, not the entire operating system. Configuration, source, logs, and databases are all persisted as files or managed storage.", "program file + operating system → running process", new(ExerciseKind.MultipleChoice, "Choose the term", "What is a running instance of a program called?", ["Choose one answer"], null, "process", [new("process", "A process"), new("class", "A class"), new("domain", "A domain name")], "The operating system schedules running program instances.", ["Distinguishes programs and processes"]), "internet-network-addresses", WebFoundations),
        new("internet-network-addresses", "Computing & internet foundations", 4, "Networks and addresses", "Networks move packets between named machines.", "IP addresses identify network destinations; ports identify a service on that destination.", "Data travels through routers in packets. An address such as `203.0.113.10` identifies a machine or network interface; `:443` identifies the HTTPS service conventionally listening there. Packets can be delayed, lost, duplicated, or reordered.", "https://example.com:443/lessons", new(ExerciseKind.MultipleChoice, "Identify the purpose", "What does a port help identify?", ["Choose one answer"], null, "service", [new("service", "A service or process on a host"), new("person", "A person using the app"), new("file", "A source-code file")], "One machine can serve multiple networked applications.", ["Explains ports"]), "internet-dns", WebFoundations),
        new("internet-dns", "Computing & internet foundations", 5, "DNS turns names into addresses", "Humans use names; networks route to addresses.", "DNS resolves a domain name to records such as IP addresses.", "Before a browser can contact `learn.example`, it generally asks DNS for an address, often using cached answers first. DNS is a distributed naming system; failed or stale resolution is a real production failure mode.", "learn.example → DNS lookup → IP address", new(ExerciseKind.MultipleChoice, "Follow the lookup", "What is DNS primarily used for?", ["Choose one answer"], null, "name", [new("name", "Finding an address for a domain name"), new("encrypt", "Encrypting application data"), new("compile", "Compiling C# code")], "The name system connects a domain to network records.", ["Explains DNS"]), "internet-http", WebFoundations),
        new("internet-http", "Computing & internet foundations", 6, "HTTP is a request and response contract", "The web is built from messages between clients and servers.", "HTTP defines methods, URLs, headers, status codes, and bodies.", "A browser or app sends a request to a server; the server returns a response. `GET` asks to read a resource, while `POST` commonly asks the server to create work. HTTP does not guarantee a request reaches the server or that a response reaches the caller.", "GET /lessons/42 HTTP/1.1\n\nHTTP/1.1 200 OK", new(ExerciseKind.MultipleChoice, "Read the exchange", "Which part tells a client whether an HTTP request succeeded?", ["Choose one answer"], null, "status", [new("status", "The response status code"), new("domain", "The C# namespace"), new("variable", "A local variable")], "Status codes communicate the server's outcome.", ["Reads HTTP outcomes"]), "internet-https", WebFoundations),
        new("internet-https", "Computing & internet foundations", 7, "HTTPS protects traffic in transit", "HTTPS is HTTP carried over TLS.", "TLS authenticates the server and protects data from passive reading and tampering in transit.", "HTTPS does not make an application automatically safe: the server still must authorize users, validate input, protect data at rest, and avoid leaking secrets. Certificates let clients verify they reached the intended service.", "browser ⇄ TLS ⇄ HTTPS server", new(ExerciseKind.MultipleChoice, "Choose the protection", "What does TLS primarily add to an HTTPS connection?", ["Choose one answer"], null, "transit", [new("transit", "Authentication and encryption in transit"), new("database", "Automatic database backups"), new("authorization", "Permission for every user action")], "Transport protection and authorization solve different problems.", ["Separates TLS and authorization"]), "internet-web-apps", WebFoundations),
        new("internet-web-apps", "Computing & internet foundations", 8, "Browsers, servers, and APIs", "A web application has cooperating clients and services.", "Browsers render user interfaces; servers apply rules and manage shared state; APIs are their contracts.", "HTML, CSS, and JavaScript create the browser experience. A C# API can validate a request, apply a business rule, read a database, and return JSON. Keep client convenience separate from server-side authorization and data integrity.", "browser → HTTPS API → database → JSON response", new(ExerciseKind.MultipleChoice, "Place the rule", "Where must a rule that protects shared data ultimately be enforced?", ["Choose one answer"], null, "server", [new("server", "On the trusted server boundary"), new("button", "Only by hiding a browser button"), new("css", "In a stylesheet")], "Client UI checks improve experience but cannot enforce trust.", ["Identifies trust boundaries"]), "internet-latency-reliability", WebFoundations),
        new("internet-latency-reliability", "Computing & internet foundations", 9, "Latency, failure, and retries", "A network call is never an instant or certainty.", "Distributed systems must set timeouts, classify failures, and make repeated work safe.", "A slow dependency can consume every server connection. Set bounded timeouts, retry only transient and safe operations, and use idempotency keys where repetition could create a duplicate effect. Measure user-visible latency instead of guessing.", "timeout + bounded retry + idempotency key", new(ExerciseKind.MultipleChoice, "Retry safely", "When is a retry most defensible?", ["Choose one answer"], null, "safe", [new("safe", "A transient failure on an idempotent operation with a limit"), new("invalid", "A caller validation failure"), new("payment", "A payment request with no duplicate protection")], "Retries can repeat effects.", ["Frames distributed failure"]), "foundations-how-code-works", WebFoundations),
        new("foundations-how-code-works", "Programming foundations", 10, "How code works", "Give the computer one clear instruction at a time.", "A program is a precise sequence of instructions transformed from source code into running behavior.", "C# source is compiled, then the .NET runtime executes it. Start by reading code top-to-bottom, predicting one expression at a time, and using output to check your mental model.", "Console.WriteLine(\"Hello, Pathway!\");", new(ExerciseKind.MultipleChoice, "Read the program", "What does this line do?", ["Choose one answer"], null, "print", [new("store", "Stores a message for later"), new("print", "Prints a message to the console"), new("loop", "Repeats the message forever")], "Look at the word after the dot: `WriteLine`.", ["Identifies console output"]), "foundations-values", TypeSystem),
        new("foundations-values", "Programming foundations", 11, "Values and variables", "Name information so your program can use it.", "Variables give values meaningful names and types communicate permitted operations.", "Prefer descriptive names and the narrowest meaningful type. Use `var` when the right-hand side makes the type obvious; it is still statically typed C#, not dynamic typing.", "string learner = \"Alex\";\nint completedLessons = 4;", new(ExerciseKind.MultipleChoice, "Choose a type", "Which type is best for a whole-number lesson count?", ["Choose one answer"], null, "int", [new("string", "string"), new("int", "int"), new("bool", "bool")], "A lesson count has no decimal places.", ["Uses a whole-number type"]), "foundations-data-types", TypeSystem),
        new("foundations-data-types", "Programming foundations", 12, "Data types carry meaning", "Choose types for the meaning and constraints of data.", "`int`, `decimal`, `bool`, `string`, `DateTimeOffset`, and `Guid` model different categories of information.", "Use `decimal` for money; binary floating-point is not appropriate for exact currency arithmetic. Use `bool` for yes/no state, `string` for text, and `DateTimeOffset` when a timestamp needs an offset. A type is part of the contract, not decoration.", "decimal price = 19.99m;\nbool isPublished = true;", new(ExerciseKind.MultipleChoice, "Model money", "Which type is the usual C# choice for currency amounts?", ["Choose one answer"], null, "decimal", [new("decimal", "decimal"), new("bool", "bool"), new("string", "string")], "Currency calculations need decimal precision.", ["Selects a meaningful type"]), "foundations-operators", TypeSystem),
        new("foundations-operators", "Programming foundations", 13, "Operators and comparisons", "Expressions compute new values from existing values.", "Arithmetic operators calculate; comparison operators produce booleans; logical operators combine conditions.", "Use parentheses when they make intent clearer. Avoid clever expressions that hide business meaning; give important intermediate values a name and test boundary conditions such as zero, empty input, and maximum values.", "var mayEnroll = age >= 13 && hasConsent;", new(ExerciseKind.MultipleChoice, "Read the condition", "What type does `age >= 13` produce?", ["Choose one answer"], null, "bool", [new("bool", "bool"), new("int", "int"), new("string", "string")], "A comparison answers true or false.", ["Reads boolean expressions"]), "foundations-making-decisions", TypeSystem),
        new("foundations-making-decisions", "Programming foundations", 14, "Making decisions", "Use conditions to choose a path.", "A boolean expression evaluates to `true` or `false`.", "An `if` statement runs its body only when its condition is true. Name complex conditions, make expected and invalid paths explicit, and test the boundary—not just one happy-path value.", "if (age >= 13)\n{\n    Console.WriteLine(\"Welcome in!\");\n}", new(ExerciseKind.Code, "Movie night", "Print `You can watch!` only when `age` is 13 or above.", ["Use an `if` statement", "Use `age >= 13`", "Print the exact message"], "int age = 16;\n\n// Write your if statement below\n", null, [], "Check the condition uses `age >= 13`, then call `Console.WriteLine` inside the braces.", ["Prints message at 13", "Does not print under 13"]), "foundations-loops", TypeSystem),
        new("foundations-loops", "Programming foundations", 15, "Repeat work with collections", "Loops apply a clear operation to each item.", "`foreach` is a strong default when you need each item, while LINQ can express transformations declaratively.", "Keep loops small and avoid changing a collection while iterating it. Use `break` or `continue` sparingly; extracting a method is often clearer. Later, learn LINQ, but first be able to trace one item through a loop.", "foreach (var lesson in lessons)\n    Console.WriteLine(lesson.Title);", new(ExerciseKind.MultipleChoice, "Choose the default", "Which construct clearly visits every item in a collection?", ["Choose one answer"], null, "foreach", [new("foreach", "foreach"), new("sealed", "sealed"), new("record", "record")], "A foreach loop expresses iteration over items.", ["Traces iteration"]), "foundations-methods", TypeSystem),
        new("foundations-methods", "Programming foundations", 16, "Methods create useful boundaries", "Name a behavior, state its inputs, and return a result.", "A focused method is easier to read, test, reuse, and change.", "Prefer methods that do one coherent job. Make dependencies and inputs explicit, return values rather than printing deep in logic, and keep side effects near boundaries. A method signature is a promise to its callers.", "static bool CanEnroll(int age, bool hasConsent)\n    => age >= 13 && hasConsent;", new(ExerciseKind.MultipleChoice, "Find the contract", "What should a method signature make clear?", ["Choose one answer"], null, "inputs", [new("inputs", "Its inputs and result"), new("colors", "Its preferred UI colors"), new("server", "Its deployment region")], "Callers need to know what to supply and what to expect.", ["States method contracts"]), "foundations-null-errors", TypeSystem),
        new("foundations-null-errors", "Programming foundations", 17, "Null, parsing, and expected errors", "Not every string is valid data and not every value exists.", "Nullable reference types and `TryParse` make absence and invalid input explicit.", "Enable nullable reference types. Use `TryParse` for expected user-input failure; use exceptions for exceptional conditions, then add context or handle them at a boundary. Never use the null-forgiving `!` merely to silence a warning you do not understand.", "if (int.TryParse(text, out var count))\n    return count;", new(ExerciseKind.MultipleChoice, "Handle input", "What does `TryParse` help avoid for expected bad input?", ["Choose one answer"], null, "exception", [new("exception", "Using an exception for ordinary invalid input"), new("type", "Using C# types"), new("test", "Writing tests")], "Parsing user input is a normal uncertainty.", ["Handles expected failure"]), "foundations-collections-debugging", TypeSystem),
        new("foundations-collections-debugging", "Programming foundations", 18, "Collections and debugging", "Store groups deliberately and investigate behavior with evidence.", "Arrays, `List<T>`, dictionaries, and sets have different lookup and ordering properties.", "Use a `List<T>` for ordered items, `Dictionary<TKey,TValue>` for key lookup, and `HashSet<T>` for membership. Debug by reproducing the smallest case, reading the exception and stack trace, inspecting state, then adding a regression test.", "var byId = new Dictionary<Guid, Lesson>();", new(ExerciseKind.MultipleChoice, "Choose lookup", "Which collection is designed to find a value by a unique key?", ["Choose one answer"], null, "dictionary", [new("dictionary", "Dictionary<TKey, TValue>"), new("list", "List<T>"), new("string", "string")], "A dictionary maps keys to values.", ["Chooses a collection"]), "objects-purpose", TypeSystem),
        new("objects-purpose", "Objects & modeling", 19, "What an object is actually for", "Objects protect a concept's state and behavior—not just a real-world noun.", "An object groups data with the operations and invariants that keep that data valid.", "Create an object when a concept has rules worth preserving in one place. An `Enrollment` should control what it means to cancel or complete, rather than letting every caller assign arbitrary fields. Simple data does not always need a class.", "enrollment.Cancel(actor, clock); // preserves the cancellation rule", new(ExerciseKind.MultipleChoice, "Choose the purpose", "What is the strongest reason to introduce an object?", ["Choose one answer"], null, "invariant", [new("invariant", "It owns rules that keep related state valid"), new("noun", "Every noun needs a class"), new("inherit", "It must be inherited")], "Objects earn their place by protecting meaning.", ["Explains object purpose"]), "objects-references", ObjectDesign),
        new("objects-references", "Objects & modeling", 20, "Classes, objects, and references", "A class defines a type; `new` creates an object; a class variable holds a reference.", "Two variables can refer to the same mutable class object.", "Understand aliasing before mutating state: changing an object through one reference is observable through another. Value types copy their value; reference types copy the reference. Prefer immutable value objects when sharing should be safe.", "var first = new Lesson();\nvar second = first; // both refer to one object", new(ExerciseKind.MultipleChoice, "Predict the effect", "If two variables reference the same mutable object, a change through one is visible through…", ["Choose one answer"], null, "both", [new("both", "Both variables"), new("neither", "Neither variable"), new("copy", "Only an automatic deep copy")], "A reference is not a clone.", ["Understands references"]), "objects-encapsulation", ObjectDesign),
        new("objects-encapsulation", "Objects & modeling", 21, "Encapsulation and invariants", "Expose intentional operations instead of a bag of writable state.", "Access modifiers and methods let a type defend its own rules.", "Keep fields private by default. Use properties for controlled exposure and methods for state transitions that require validation. An invariant is a fact that must remain true after construction and every public operation.", "public int SeatsRemaining { get; private set; }", new(ExerciseKind.MultipleChoice, "Protect the state", "Why might a property have a private setter?", ["Choose one answer"], null, "rule", [new("rule", "Only the type can enforce its state-change rules"), new("fast", "It makes every call faster"), new("json", "It automatically encrypts JSON")], "The type should control changes that affect its invariants.", ["Protects invariants"]), "objects-constructors", ObjectDesign),
        new("objects-constructors", "Objects & modeling", 22, "Construct valid objects", "Construction is the first chance to establish invariants.", "Constructors require the information a type needs to be valid.", "Reject invalid required input early. Use object initializers and `required` properties where they make a type clearer, but do not allow a partially valid domain object to escape. Primary constructors suit straightforward dependency capture, not complex construction logic.", "public sealed class Lesson(string title)\n{\n    public string Title { get; } = title;\n}", new(ExerciseKind.MultipleChoice, "Choose the moment", "When should a required invariant first be established?", ["Choose one answer"], null, "construct", [new("construct", "During construction"), new("database", "Only after saving to the database"), new("ui", "Only when the UI displays it")], "Invalid objects make every later method harder.", ["Constructs valid state"]), "modern-csharp-records", ObjectDesign),
        new("modern-csharp-records", "Objects & modeling", 23, "Model data with records", "Use value-based data types for immutable messages and responses.", "Records express data-focused types with value equality.", "A positional record is a concise choice for immutable request, response, and message DTOs. Use `with` to create a changed copy rather than mutating the original. Do not mistake records for a universal replacement for behavior-rich domain objects.", "public sealed record OrderResponse(Guid Id, string Status);\nvar shipped = order with { Status = \"Shipped\" };", new(ExerciseKind.Code, "Order response", "Declare an `Order` record with an `Id` and a `Status`.", ["Use the `record` keyword", "Name the type `Order`", "Include `Id` and `Status`"], "// Create a data-focused Order type\n", null, [], "Start with: `public sealed record Order(...)`. Choose suitable types for the two values.", ["Declares a record", "Uses the expected type name"]), "objects-composition-interfaces", TypeSystem),
        new("objects-composition-interfaces", "Objects & modeling", 24, "Composition and interfaces", "Vary behavior through small contracts and collaborators.", "Composition is usually safer than inheritance for application behavior.", "An interface describes what a collaborator can do, allowing a type to depend on a stable capability rather than a concrete implementation. Keep interfaces focused on a real boundary; do not create one automatically for every class.", "public interface IClock { DateTimeOffset UtcNow { get; } }", new(ExerciseKind.MultipleChoice, "Choose the seam", "What should a useful interface represent?", ["Choose one answer"], null, "capability", [new("capability", "A focused capability a collaborator needs"), new("class", "Every concrete class by default"), new("inherit", "A mandatory inheritance hierarchy")], "Good abstractions serve a real change or testing boundary.", ["Uses composition seams"]), "web-api-sealed-services", ObjectDesign),
        new("web-api-sealed-services", "Objects & modeling", 25, "Design closed Web API types", "Default to closed concrete types; open types deliberately.", "`sealed` prevents unintended inheritance. Prefer composition and interfaces for variation.", "For a concrete application service or controller that is not designed as an extension point, `sealed` makes that decision explicit. It is not universal: do not seal framework extension points, deliberately extensible libraries, or types that must be proxied. Use constructor injection and accept `CancellationToken` at I/O boundaries.", "public sealed class OrdersController(IOrderService orders) : ControllerBase\n{\n    public async Task<OrderResponse> Get(Guid id, CancellationToken ct)\n        => await orders.GetAsync(id, ct);\n}", new(ExerciseKind.Code, "Close the service", "Create a sealed `OrderService` that implements `IOrderService` and accepts a `CancellationToken` in an async operation.", ["Declare a `sealed class`", "Implement `IOrderService`", "Accept `CancellationToken`"], "// Prefer composition over inheritance.\n", null, [], "Use `public sealed class OrderService : IOrderService`. Add an async method with a `CancellationToken` parameter.", ["Prevents inheritance", "Supports cancellation"]), "modern-csharp-switch-expressions", AspNetCore),
        new("modern-csharp-switch-expressions", "Modern C#", 26, "Express branches as values", "Use switch expressions when every case produces a value.", "A switch expression is compact and encourages exhaustive handling.", "When a decision maps an input to one result, a switch expression is often clearer than a multi-branch `if` chain. Add a discard arm when unknown values have a safe fallback.", "var label = status switch { OrderStatus.Paid => \"Ready\", _ => \"Pending\" };", new(ExerciseKind.MultipleChoice, "Pick the pattern", "When is a switch expression a strong fit?", ["Choose the best answer"], null, "maps", [new("maps", "Several input cases each produce one value"), new("sideeffects", "Each branch performs unrelated effects"), new("inheritance", "A class needs a base type")], "Look for a decision that returns a value.", ["Recognizes value mapping"]), "modern-csharp-primary-constructors", Current),
        new("modern-csharp-primary-constructors", "Modern C#", 27, "Use primary constructors deliberately", "Keep straightforward dependencies close to the type they support.", "Primary constructor parameters are available throughout the type body; they are not automatically properties except for records.", "Use a primary constructor for a small service with direct dependencies. Use an ordinary constructor when validation, transformation, overloads, or substantial construction work makes that story clearer.", "public sealed class PriceService(IExchangeRateClient rates)\n{\n    public Task<decimal> ConvertAsync(decimal amount, CancellationToken ct) => rates.ConvertAsync(amount, ct);\n}", new(ExerciseKind.MultipleChoice, "Choose the fit", "When is a primary constructor most useful?", ["Choose the best answer"], null, "dependency", [new("dependency", "A small service uses an injected dependency"), new("complex", "A type needs substantial construction logic"), new("static", "A static helper has no instance state")], "Choose clarity over shorter syntax.", ["Identifies a primary constructor use case"]), "modern-csharp-ranges", Current),
        new("modern-csharp-ranges", "Modern C#", 28, "Slice safely with ranges", "Use ranges to express positions and slices clearly.", "The range operator `..` describes a start and end; `^` counts backward.", "Ranges make intent clear for strings, arrays, and spans. In performance-sensitive code, learn whether an API allocates a new value or exposes a view; measure before optimizing.", "var lastFour = cardNumber[^4..];\nvar prefix = cardNumber[..4];", new(ExerciseKind.MultipleChoice, "Read the range", "What does `values[^2..]` select?", ["Choose one answer"], null, "last", [new("first", "The first two values"), new("last", "The final two values"), new("all", "Every value except the final two")], "`^2` means two positions from the end.", ["Reads from-end indexes"]), "modern-csharp-linq", Current),
        new("modern-csharp-linq", "Modern C#", 29, "Query collections with LINQ", "Use LINQ to make transformations and queries visible.", "LINQ composes filtering, projection, grouping, and aggregation over sequences.", "Prefer a readable pipeline over a clever one. Know when execution is deferred and avoid enumerating expensive sequences repeatedly. Materialize deliberately when you need a stable result or are crossing an I/O boundary.", "var titles = lessons.Where(x => x.IsPublished).Select(x => x.Title).ToList();", new(ExerciseKind.MultipleChoice, "Read the pipeline", "What does `Where` do in a LINQ query?", ["Choose one answer"], null, "filter", [new("filter", "Filters items by a condition"), new("sort", "Always sorts items"), new("save", "Saves items to a database")], "Where selects items that meet a predicate.", ["Reads LINQ filters"]), "modern-csharp-async", Current),
        new("modern-csharp-async", "Modern C#", 30, "Async is about waiting", "Avoid blocking threads while I/O is in flight.", "`async` and `await` compose asynchronous operations; they do not make CPU work free or automatically parallel.", "Use async APIs all the way through an I/O path, await tasks, bound concurrent fan-out, and do not block with `.Result` or `.Wait()`. Move CPU-bound work to an appropriate worker or compute system.", "var response = await client.GetAsync(url, cancellationToken);", new(ExerciseKind.MultipleChoice, "Choose the operation", "Which workload is a natural async candidate?", ["Choose one answer"], null, "io", [new("io", "Waiting for an HTTP response"), new("cpu", "A long CPU-only calculation"), new("syntax", "Formatting source code")], "Async makes waiting more efficient.", ["Separates I/O and CPU work"]), "web-api-minimal-or-controller", Current),
        new("web-api-minimal-or-controller", "Web APIs", 31, "Choose an HTTP endpoint style", "Use the simplest API style that preserves clarity.", "ASP.NET Core supports Minimal APIs and controller-based APIs.", "Minimal APIs are excellent for small, focused endpoints. Controllers can organize larger endpoint groups and cross-cutting conventions. Both should validate input, return appropriate HTTP semantics, honor cancellation, and keep business rules out of the endpoint.", "app.MapGet(\"/orders/{id:guid}\", async (Guid id, IOrderService orders, CancellationToken ct) => await orders.GetAsync(id, ct) is { } order ? Results.Ok(order) : Results.NotFound());", new(ExerciseKind.MultipleChoice, "Choose the shape", "Which is a good reason to choose a controller?", ["Choose one answer"], null, "organization", [new("organization", "A large API benefits from grouped actions and conventions"), new("speed", "Controllers make all requests faster"), new("inheritance", "Every endpoint must inherit from one")], "Choose based on organization, not folklore.", ["Selects an API style intentionally"]), "web-api-contracts", AspNetCore),
        new("web-api-contracts", "Web APIs", 32, "Design the contract before the handler", "An API is a promise that clients depend on.", "Methods, resource shapes, validation, errors, pagination, and idempotency are contract decisions.", "Write success and failure examples first. Prefer additive changes, consistent error envelopes, and explicit pagination semantics. Return `201 Created` for a created resource where appropriate; distinguish client mistakes from server failures.", "POST /enrollments\nIdempotency-Key: 7fd...\n\n201 Created", new(ExerciseKind.MultipleChoice, "Choose compatibility", "What is usually the least disruptive response change?", ["Choose one answer"], null, "add", [new("add", "Add an optional documented field"), new("rename", "Rename a required field immediately"), new("break", "Change success into a 500 response")], "Additive changes preserve old clients more often.", ["Designs compatible contracts"]), "web-api-validation-auth", AspNetCore),
        new("web-api-validation-auth", "Web APIs", 33, "Validate, authenticate, authorize", "Identity is not permission, and untrusted input is not a domain model.", "Authentication establishes who is calling; authorization checks whether that principal may perform this action on this resource.", "Validate request shape at the boundary, then authorize the specific action and resource in trusted server code. Use a proven identity provider, least-privilege roles or policies, and never rely on hidden UI controls as security.", "if (!authorizationService.CanEdit(user, lesson)) return Results.Forbid();", new(ExerciseKind.MultipleChoice, "Authorize the action", "What must an API check before changing a lesson?", ["Choose one answer"], null, "resource", [new("resource", "Permission for this action on this resource"), new("button", "Whether the UI hid a button"), new("token", "Only that a token exists")], "A valid identity does not grant every action.", ["Separates authentication and authorization"]), "data-databases", AspNetCore),
        new("data-databases", "Data, testing & delivery", 34, "Model durable data", "A database is a shared, concurrent contract.", "Schema, constraints, indexes, queries, and transactions determine correctness and performance.", "Use migrations as reviewed release artifacts. Keep transactions short around one business operation, parameterize queries, use database constraints for durable invariants, and choose indexes from measured access patterns. Evolve schema with expand-then-contract deployments.", "BEGIN;\nINSERT enrollment;\nINSERT outbox_event;\nCOMMIT;", new(ExerciseKind.MultipleChoice, "Protect atomicity", "What belongs in the same transaction as a new enrollment when the event must not be lost?", ["Choose one answer"], null, "outbox", [new("outbox", "A durable outbox event"), new("email", "A slow remote email call"), new("cache", "An unrelated cache warm-up")], "The outbox links committed state and durable intent.", ["Defines transaction boundaries"]), "quality-tests", AspNetCore),
        new("quality-tests", "Data, testing & delivery", 35, "Prove behavior with tests", "Tests protect behavior, not implementation trivia.", "A useful test names a behavior and gives clear failure feedback.", "Write focused unit tests for domain logic and integration tests for boundaries—HTTP, databases, queues, and authentication. Test observable contracts; avoid coupling tests to private helper order. Keep a small end-to-end suite for critical journeys.", "[Fact]\npublic async Task Get_returns_404_when_missing()\n{\n    var response = await _client.GetAsync(\"/orders/not-found\");\n    response.StatusCode.Should().Be(HttpStatusCode.NotFound);\n}", new(ExerciseKind.MultipleChoice, "Test the contract", "What should an endpoint integration test assert first?", ["Choose one answer"], null, "observable", [new("observable", "The status code and response contract"), new("private", "The private helper call order"), new("logging", "An exact timestamp in every log")], "A client cannot rely on private implementation details.", ["Focuses on observable behavior"]), "reliability-cancellation", Current),
        new("reliability-cancellation", "Data, testing & delivery", 36, "Propagate cancellation", "Stop work when the caller no longer needs it.", "`CancellationToken` is a cooperative signal, not an exception to ignore.", "Accept a token at request and job boundaries, then pass it to database, HTTP, and async APIs that support it. Do not create a new token deep in the call chain. Treat cancellation as expected control flow, not an application error.", "public Task<Order?> GetAsync(Guid id, CancellationToken ct) => _db.Orders.SingleOrDefaultAsync(x => x.Id == id, ct);", new(ExerciseKind.MultipleChoice, "Follow the token", "What should a request handler do with its cancellation token?", ["Choose one answer"], null, "propagate", [new("propagate", "Pass it to downstream async and I/O calls"), new("ignore", "Ignore it because the server can finish later"), new("replace", "Create a new token for every method")], "Cancellation only helps if work that can stop receives the token.", ["Propagates cancellation"]), "reliability-http-clients", AspNetCore),
